CREATE TEMP TABLE v ON COMMIT DROP AS SELECT c.cnpj_orgao org, c.categoria_saude cat, r.ni_fornecedor forn, coalesce(r.ano, extract(year from r.data_resultado)::int) ano, r.valor_unitario_homologado / i.valor_unitario_estimado ratio FROM resultados r JOIN itens i ON i.numero_controle_pncp = r.numero_controle_pncp AND i.numero_item = r.numero_item JOIN contratacoes c ON c.numero_controle_pncp = r.numero_controle_pncp WHERE c.modalidade_nome LIKE 'Pregão%' AND i.valor_unitario_estimado > 0 AND r.valor_unitario_homologado > 0 AND r.valor_unitario_homologado <> i.valor_unitario_estimado AND r.valor_unitario_homologado / i.valor_unitario_estimado > 0.05 AND r.valor_unitario_homologado / i.valor_unitario_estimado <= 1.5;
-- Q25 fallback: itens de 2026 cujo órgão+categoria NÃO tinha amostra em 2025, mas o órgão tinha. Previsão pela mediana do órgão inteiro vs categoria nacional
WITH mc AS (SELECT cat, percentile_cont(0.5) WITHIN GROUP (ORDER BY ratio) m, percentile_cont(0.25) WITHIN GROUP (ORDER BY ratio) lo, percentile_cont(0.75) WITHIN GROUP (ORDER BY ratio) hi FROM v WHERE ano = 2025 GROUP BY cat),
oc AS (SELECT org, cat, count(*) n FROM v WHERE ano = 2025 GROUP BY 1,2),
og AS (SELECT org, percentile_cont(0.5) WITHIN GROUP (ORDER BY ratio) m, percentile_cont(0.25) WITHIN GROUP (ORDER BY ratio) lo, percentile_cont(0.75) WITHIN GROUP (ORDER BY ratio) hi FROM v WHERE ano = 2025 GROUP BY org HAVING count(*) >= 30),
t AS (SELECT v.* FROM v LEFT JOIN oc USING (org, cat) WHERE v.ano = 2026 AND coalesce(oc.n, 0) < 30)
SELECT count(*) itens, round(percentile_cont(0.5) WITHIN GROUP (ORDER BY abs(t.ratio - og.m))::numeric,3) erro_orgao_geral, round(percentile_cont(0.5) WITHIN GROUP (ORDER BY abs(t.ratio - mc.m))::numeric,3) erro_categoria_nacional, round(100.0*avg((t.ratio BETWEEN og.lo AND og.hi)::int),1) dentro_orgao, round(avg(og.hi-og.lo)::numeric,3) larg_orgao, round(100.0*avg((t.ratio BETWEEN mc.lo AND mc.hi)::int),1) dentro_cat, round(avg(mc.hi-mc.lo)::numeric,3) larg_cat FROM t JOIN og USING (org) JOIN mc USING (cat)
